  ["PERFECT!"] = "PERFEKT!",
  ["Spot on!"] = "Genau richtig!",
  ["Bullseye!"] = "Volltreffer!",
  ["Flawless!"] = "Makellos!",
  ["Right on the beat!"] = "Genau im Takt!",
  ["Nice timing!"] = "Gutes Timing!",
  ["Sharp!"] = "Scharf!",
  ["Excellent!"] = "Ausgezeichnet!",
  ["Well played!"] = "Gut gespielt!",
  ["Not bad"] = "Nicht schlecht",
