  ["Keep it up"] = "Weiter so",
  ["Nice try"] = "Netter Versuch",
  ["Oh, too bad..."] = "Oh, schade ...",
  ["Missed!"] = "Verfehlt!",
  ["So close..."] = "So knapp ...",
  ["Shake it off"] = "Abhaken",
  ["Next one!"] = "Die Nächste!",
  ["Great streak!"] = "Tolle Serie!",
  ["Keep it up!"] = "Weiter so!",
  ["Blazing!"] = "Lodernd!",
  ["Streak Champion!"] = "Serienmeister!",
  ["Godlike!"] = "Göttlich!",
  ["Immortal!"] = "Unsterblich!",
  ["Game timing offset"] = "Spielmodus-Zeitversatz",
  ["Game mode: moves the moment a note reaches the line (and flashes). If your presses feel late, raise it: the note arrives that much sooner. Like a rhythm game's calibration."] = "Spielmodus: verschiebt den Moment, in dem eine Note die Linie erreicht (und aufblitzt). Fühlen sich deine Tastendrücke spät an, erhöhe ihn: Die Note kommt entsprechend früher an. Wie die Kalibrierung eines Rhythmusspiels.",
  ["Game score %d, best streak %d, %d%% perfect"] = "Spielpunkte %d, beste Serie %d, %d%% perfekt",
  ["(new high score)"] = "(neuer Höchststand)",
  ["Clears the best streak and best set score of the spec you are in. Other specs keep theirs."] = "Löscht die beste Serie und die beste Satzpunktzahl der Spezialisierung, in der du bist. Andere Spezialisierungen behalten ihre.",
  ["Core"] = "Kern",
  ["Core settings"] = "Kerneinstellungen",
  ["Describe what went wrong, copy the report, and open the issue page (also /dmga report)."] = "Beschreibe, was schiefging, kopiere den Bericht und öffne die Fehlerseite (auch /dmga report).",
  ["Forget this spec's game records"] = "Spielrekorde dieser Spezialisierung vergessen",
  ["Four questions: where the HUD goes, how big, when it shows, and classic or Game mode."] = "Vier Fragen: wo das HUD hinkommt, wie groß, wann es erscheint, und klassisch oder Spielmodus.",
  ["Game mode & grades"] = "Spielmodus & Bewertungen",
  ["Game records for this spec forgotten."] = "Spielrekorde dieser Spezialisierung vergessen.",
  ["How DMGAssist thinks and looks: Combat, Display, Sounds, Integrations, Spells & trinkets and Advanced, on the pages below."] = "Wie DMGAssist denkt und aussieht: Kampf, Anzeige, Sounds, Integrationen, Zauber & Schmuckstücke und Erweitert, auf den Seiten darunter.",
  ["Play the HUD like a rhythm game, or keep the classic icons. Switch any time with the drum button on the HUD, /dmga game, or a key binding."] = "Spiele das HUD wie ein Rhythmusspiel oder behalte die klassischen Symbole. Jederzeit umschaltbar mit der Trommel am HUD, /dmga game oder einer Tastenbelegung.",
  ["Records"] = "Rekorde",
  ["Report"] = "Melden",
  ["Status & Help"] = "Status & Hilfe",
  ["Turn DMGAssist on or off, move it, and pick its language. Everything else is in three groups below: Status & Help, Core (Combat, Display, Sounds, Integrations, Advanced) and Game mode & grades."] = "Schalte DMGAssist ein oder aus, verschiebe es und wähle die Sprache. Alles andere ist in drei Gruppen darunter: Status & Hilfe, Kern (Kampf, Anzeige, Sounds, Integrationen, Erweitert) und Spielmodus & Bewertungen.",
  ["What DMGAssist sees right now (Status), how to use it (Help), and spells it may recommend that have no key yet (Missing keybinds): the pages below."] = "Was DMGAssist gerade sieht (Status), wie man es benutzt (Hilfe) und empfohlene Zauber ohne Taste (Fehlende Tastenbelegungen): die Seiten darunter.",
  ["KICK!"] = "UNTERBRECHEN!",
  ["DEFEND!"] = "VERTEIDIGEN!",
  ["POWER UP!"] = "POWER-UP!",
  ["Interrupted!"] = "Unterbrochen!",
  ["Safe!"] = "Sicher!",
  ["Powered up!"] = "Aufgeladen!",
  ["Bonus +%d"] = "Bonus +%d",
  ["Play the HUD like a rhythm game: notes slide right to left into a line and reach it when the spell can be pressed. Interrupts, defensives and trinkets pop into the bonus row above it. Hits build a streak; 5, 10, 25, 50 in a row earn a star. Switch any time with the drum button on the HUD or /dmga game."] = "Spiele das HUD wie ein Rhythmusspiel: Noten gleiten von rechts nach links zu einer Linie und erreichen sie, wenn der Zauber gedrückt werden kann. Unterbrechungen, Verteidigungen und Schmuckstücke erscheinen in der Bonusreihe darüber. Treffer bauen eine Serie auf; 5, 10, 25, 50 in Folge bringen einen Stern. Jederzeit umschalten mit der Trommel am HUD oder /dmga game.",
  ["POWER MODE!"] = "POWER-MODUS!",
  ["AOE"] = "AOE",
  ["PERFECT x%d"] = "PERFEKT x%d",
  ["CLASSIC"] = "KLASSISCH",
  ["GAME"] = "SPIEL",
  ["Game mode on: hit each note as it reaches the line. Click the CLASSIC / GAME switch (or /dmga game) to switch back."] = "Spielmodus an: Triff jede Note, wenn sie die Linie erreicht. Klicke den Schalter KLASSISCH / SPIEL (oder /dmga game), um zurückzuschalten.",
  ["Play the HUD like a rhythm game, or keep the classic icons. Switch any time with the CLASSIC / GAME switch above the HUD, /dmga game, or a key binding."] = "Spiele das HUD wie ein Rhythmusspiel oder behalte die klassischen Symbole. Jederzeit umschaltbar mit dem Schalter KLASSISCH / SPIEL über dem HUD, /dmga game oder einer Tastenbelegung.",
  ["Play the HUD like a rhythm game: notes slide right to left into a line and reach it when the spell can be pressed. Interrupts, defensives and trinkets pop into the bonus row above it. Hits build a streak; 5, 10, 25, 50 in a row earn a star. Switch any time with the CLASSIC / GAME switch above the HUD or /dmga game."] = "Spiele das HUD wie ein Rhythmusspiel: Noten gleiten von rechts nach links zu einer Linie und erreichen sie, wenn der Zauber gedrückt werden kann. Unterbrechungen, Verteidigungen und Schmuckstücke erscheinen in der Bonusreihe darüber. Treffer bauen eine Serie auf; 5, 10, 25, 50 in Folge bringen einen Stern. Jederzeit umschalten mit dem Schalter KLASSISCH / SPIEL über dem HUD oder /dmga game.",
  ["Which style? (Switch any time with the CLASSIC / GAME switch above the HUD, or /dmga game.)"] = "Welcher Stil? (Jederzeit umschaltbar mit dem Schalter KLASSISCH / SPIEL über dem HUD oder /dmga game.)",
  ["FLOW"] = "FLOW",
  ["Flow mode"] = "Flow-Modus",
  ["Flow mode & grades"] = "Flow-Modus & Bewertungen",
  ["Flow mode off: the classic HUD is back."] = "Flow-Modus aus: Das klassische HUD ist zurück.",
  ["Flow mode on: hit each note as it reaches the line. Click the CLASSIC / FLOW switch (or /dmga flow) to switch back."] = "Flow-Modus an: Triff jede Note, wenn sie die Linie erreicht. Klicke den Schalter KLASSISCH / FLOW (oder /dmga flow), um zurückzuschalten.",
  ["Flow mode: moves the moment a note reaches the line (and flashes). If your presses feel late, raise it: the note arrives that much sooner. Like a rhythm game's calibration."] = "Flow-Modus: verschiebt den Moment, in dem eine Note die Linie erreicht (und aufblitzt). Fühlen sich deine Tastendrücke spät an, erhöhe ihn: Die Note kommt entsprechend früher an. Wie die Kalibrierung eines Rhythmusspiels.",
  ["Flow mode: notes slide into a hit line, with streaks"] = "Flow-Modus: Noten gleiten zu einer Trefferlinie, mit Serien",
  ["Flow mode: off (click to play the HUD like a rhythm game)"] = "Flow-Modus: aus (klicken, um das HUD wie ein Rhythmusspiel zu spielen)",
  ["Flow mode: on (click for the classic HUD)"] = "Flow-Modus: an (klicken für das klassische HUD)",
  ["Flow records for this spec forgotten."] = "Flow-Rekorde dieser Spezialisierung vergessen.",
  ["Flow score %d, best streak %d, %d%% perfect"] = "Flow-Punkte %d, beste Serie %d, %d%% perfekt",
  ["Flow timing offset"] = "Flow-Zeitversatz",
  ["Forget this spec's Flow records"] = "Flow-Rekorde dieser Spezialisierung vergessen",
  ["Four questions: where the HUD goes, how big, when it shows, and classic or Flow mode."] = "Vier Fragen: wo das HUD hinkommt, wie groß, wann es erscheint, und klassisch oder Flow-Modus.",
  ["Play the HUD like a rhythm game, or keep the classic icons. Switch any time with the CLASSIC / FLOW switch above the HUD, /dmga flow, or a key binding."] = "Spiele das HUD wie ein Rhythmusspiel oder behalte die klassischen Symbole. Jederzeit umschaltbar mit dem Schalter KLASSISCH / FLOW über dem HUD, /dmga flow oder einer Tastenbelegung.",
  ["Play the HUD like a rhythm game: notes slide right to left into a line and reach it when the spell can be pressed. Interrupts, defensives and trinkets pop into the bonus row above it. Hits build a streak; 5, 10, 25, 50 in a row earn a star. Switch any time with the CLASSIC / FLOW switch above the HUD or /dmga flow."] = "Spiele das HUD wie ein Rhythmusspiel: Noten gleiten von rechts nach links zu einer Linie und erreichen sie, wenn der Zauber gedrückt werden kann. Unterbrechungen, Verteidigungen und Schmuckstücke erscheinen in der Bonusreihe darüber. Treffer bauen eine Serie auf; 5, 10, 25, 50 in Folge bringen einen Stern. Jederzeit umschalten mit dem Schalter KLASSISCH / FLOW über dem HUD oder /dmga flow.",
  ["Turn DMGAssist on or off, move it, and pick its language. Everything else is in three groups below: Status & Help, Core (Combat, Display, Sounds, Integrations, Advanced) and Flow mode & grades."] = "Schalte DMGAssist ein oder aus, verschiebe es und wähle die Sprache. Alles andere ist in drei Gruppen darunter: Status & Hilfe, Kern (Kampf, Anzeige, Sounds, Integrationen, Erweitert) und Flow-Modus & Bewertungen.",
  ["Which style? (Switch any time with the CLASSIC / FLOW switch above the HUD, or /dmga flow.)"] = "Welcher Stil? (Jederzeit umschaltbar mit dem Schalter KLASSISCH / FLOW über dem HUD oder /dmga flow.)",
  ["Switch Flow mode on / off"] = "Flow-Modus an / aus",
  ["Flow mode on / off: notes slide into a hit line, streaks and stars"] = "Flow-Modus an / aus: Noten gleiten zu einer Trefferlinie, Serien und Sterne",
  ["READY, PLAYER ONE?"] = "BEREIT, SPIELER EINS?",
  ["INSERT COIN"] = "MÜNZE EINWERFEN",
  ["PRESS START"] = "START DRÜCKEN",
  ["Hit your first spell to start the Flow"] = "Wirke deinen ersten Zauber, um den Flow zu starten",
  ["LET'S GO!"] = "LOS GEHT'S!",
  ["Play the HUD like a rhythm game, or keep the classic icons. Switch any time with the CLASSIC / FLOW switch under the HUD, /dmga flow, or a key binding."] = "Spiele das HUD wie ein Rhythmusspiel oder behalte die klassischen Symbole. Jederzeit umschaltbar mit dem Schalter KLASSISCH / FLOW unter dem HUD, /dmga flow oder einer Tastenbelegung.",
  ["Play the HUD like a rhythm game: notes slide right to left into a line and reach it when the spell can be pressed. Interrupts, defensives and trinkets pop into the bonus row above it. Hits build a streak; 5, 10, 25, 50 in a row earn a star. Switch any time with the CLASSIC / FLOW switch under the HUD or /dmga flow."] = "Spiele das HUD wie ein Rhythmusspiel: Noten gleiten von rechts nach links zu einer Linie und erreichen sie, wenn der Zauber gedrückt werden kann. Unterbrechungen, Verteidigungen und Schmuckstücke erscheinen in der Bonusreihe darüber. Treffer bauen eine Serie auf; 5, 10, 25, 50 in Folge bringen einen Stern. Jederzeit umschalten mit dem Schalter KLASSISCH / FLOW unter dem HUD oder /dmga flow.",
  ["Which style? (Switch any time with the CLASSIC / FLOW switch under the HUD, or /dmga flow.)"] = "Welcher Stil? (Jederzeit umschaltbar mit dem Schalter KLASSISCH / FLOW unter dem HUD oder /dmga flow.)",
  ["PAUSED"] = "PAUSE",
  ["Hit your next spell to jump back in"] = "Wirke deinen nächsten Zauber, um wieder einzusteigen",
  ["Back in the Flow!"] = "Zurück im Flow!",
  ["This spec's shots need a bow, gun or crossbow equipped: with your current weapon they can't be used, so DMGAssist has nothing to show."] = "Die Schüsse dieser Spezialisierung brauchen einen Bogen, eine Schusswaffe oder eine Armbrust: mit deiner aktuellen Waffe sind sie nicht nutzbar, daher kann DMGAssist nichts anzeigen.",
  ["INTERRUPT!"] = "UNTERBRECHEN!",
  ["Pick your style"] = "Wähle deinen Stil",
  ["Your next three spells as icons. Press the big one."] = "Deine nächsten drei Zauber als Symbole. Drück das große.",
  ["Spells slide into the box. Press each one as it lands and build a streak."] = "Zauber gleiten in die Box. Drück jeden, sobald er ankommt, und bau eine Serie auf.",
  ["Switch any time with the CLASSIC / FLOW switch under the HUD."] = "Jederzeit umschaltbar mit dem CLASSIC-/FLOW-Schalter unter dem HUD.",
  ["%s is in slot 1 but isn't on your action bars. Drag it from the spellbook (hero talent spells are on a later page) onto a bar and give it a key, or hide it on the Spells, trinkets & potion page."] = "%s steht auf Platz 1, liegt aber auf keiner Aktionsleiste. Zieh ihn aus dem Zauberbuch (Zauber der Heldentalente stehen auf einer späteren Seite) auf eine Leiste und belege eine Taste, oder blende ihn auf der Seite Zauber, Schmuckstücke & Trank aus.",
  ["%s is shown in a small icon (defensive or off-GCD) but has no key. Put it on a bar and give it a key, or hide it on the Spells, trinkets & potion page."] = "%s wird in einem kleinen Symbol angezeigt (Verteidigung oder außerhalb der globalen Abklingzeit), hat aber keine Taste. Leg ihn auf eine Leiste und belege eine Taste, oder blende ihn auf der Seite Zauber, Schmuckstücke & Trank aus.",
  ["%s. Suggested in the items badge beside slot 1 when SimC drinks a potion (with your big cooldowns). Click the box to change it, right-click to remove it."] = "%s. Wird im Gegenstands-Abzeichen neben Platz 1 vorgeschlagen, wenn SimC einen Trank nimmt (mit deinen großen Abklingzeiten). Klicke auf das Feld, um ihn zu ändern, Rechtsklick entfernt ihn.",
  ["A tag in an icon's corner says where the pick came from: none = SimulationCraft's priority list, AC = Blizzard's Assisted Combat, B = Blizzard's written rules, ? = a best guess (also dimmed), ... = waiting for resource, BUFF = a buff to put back up before the pull. Badges at the big icon's corners: red edge = a spell to press alongside it, off the global cooldown (Ironfur, Shield Block) or a defensive; gold edge = an on-use trinket or your potion. A red-edged icon beside the HUD: interrupt now. Red text above the HUD: a warning from your boss mod."] = "Eine Markierung in der Symbolecke sagt, woher die Wahl kommt: keine = SimulationCrafts Prioritätenliste, AC = Blizzards Kampfassistent, B = Blizzards geschriebene Regeln, ? = beste Schätzung (auch abgedunkelt), ... = wartet auf Ressource, BUFF = ein Buff, den du vor dem Pull erneuern solltest. Abzeichen an den Ecken des großen Symbols: roter Rand = ein Zauber zum Mitdrücken, außerhalb der globalen Abklingzeit (Eisenfell, Schildblock) oder ein Defensivzauber; goldener Rand = ein Schmuckstück mit Benutzen-Effekt oder dein Trank. Ein rot umrandetes Symbol neben dem HUD: jetzt unterbrechen. Roter Text über dem HUD: eine Warnung deines Boss-Addons.",
  ["After a set of pulls, a grade from S+ to D in both modes: pressing the spell shown (accuracy), never sitting idle while it's ready (always be casting), how quickly you press it (reaction) and how soon you use big cooldowns, trinkets and potions. It never claims damage: the game's damage meter shows that. Flow mode & grades > Grade report has your best, your recent sets and where to improve."] = "Nach einer Reihe von Pulls eine Note von S+ bis D, in beiden Modi: den gezeigten Zauber drücken (Genauigkeit), nie untätig sein, wenn er bereit ist (immer zaubern), wie schnell du drückst (Reaktion) und wie bald du große Abklingzeiten, Schmuckstücke und Tränke nutzt. Sie behauptet nie etwas über Schaden: das zeigt der Schadensmesser des Spiels. Flow-Modus & Bewertungen > Notenbericht zeigt deine beste Note, die letzten Durchgänge und wo du besser werden kannst.",
  ["Big icon (NOW): press it. A dark shade over it counts down until it can be pressed, then it flashes. Small icons (NEXT): what comes after it. Gold bar under the icons: your global cooldown. Title row: the target mode and how many enemies are counted (AUTO · AOE 3 targets). Red icon: your target is out of that spell's range. Blue big icon: not enough resource yet. HOLD over the big icon: you are channeling, let it finish. \"5 » 6\" under it: you pressed 5, the big icon wanted 6."] = "Großes Symbol (JETZT): drücke es. Ein dunkler Schatten zählt herunter, bis es geht, dann blinkt es. Kleine Symbole (NÄCHSTE): was danach kommt. Goldener Balken unter den Symbolen: deine globale Abklingzeit. Titelzeile: Zielmodus und wie viele Gegner gezählt werden (AUTO · AOE 3 Ziele). Rotes Symbol: dein Ziel ist außer Reichweite dieses Zaubers. Blaues großes Symbol: noch nicht genug Ressource. HOLD über dem großen Symbol: du kanalisierst, lass es auslaufen. \"5 » 6\" darunter: du hast 5 gedrückt, gewollt war 6.",
  ["Boss mods, Masque, bar addons and the tests for them."] = "Boss-Addons, Masque, Leisten-Addons und die Tests dafür.",
  ["Classic: tags and badges"] = "Klassisch: Markierungen und Abzeichen",
  ["Classic: what you see"] = "Klassisch: was du siehst",
  ["Combat, Display, Sounds, Integrations, Advanced, and your spells, trinkets and potion."] = "Kampf, Anzeige, Klänge, Integrationen, Erweitert sowie deine Zauber, Schmuckstücke und dein Trank.",
  ["Core is a group: its settings are on the pages inside it. Click the + beside Core on the left to see them, or open one here."] = "Kern ist eine Gruppe: die Einstellungen stehen auf den Seiten darin. Klicke links auf das + neben Kern, um sie zu sehen, oder öffne eine hier.",
  ["Custom: how big the icons are and the space between them. To move them, unlock on the first page and drag, or use Blizzard's Edit Mode."] = "Benutzerdefiniert: wie groß die Symbole sind und der Abstand dazwischen. Zum Verschieben auf der ersten Seite entsperren und ziehen, oder Blizzards Bearbeitungsmodus nutzen.",
  ["DMGAssist shows your rotation in two ways, and both always agree on the spell to press now. CLASSIC: three icons; the big one is the spell to press, the two small ones come after it. FLOW: the same spells slide along a lane into a box like a rhythm game; press each one as it lands to build a streak and a score. Switch any time with the CLASSIC / FLOW switch under the HUD, /dmga flow, or the minimap menu."] = "DMGAssist zeigt deine Rotation auf zwei Arten, und beide sind sich beim Zauber für jetzt immer einig. KLASSISCH: drei Symbole; das große ist der Zauber, den du drückst, die zwei kleinen folgen danach. FLOW: dieselben Zauber gleiten wie in einem Rhythmusspiel über eine Spur in ein Feld; drücke jeden, wenn er ankommt, und baue eine Serie und Punkte auf. Wechsle jederzeit mit dem Schalter KLASSISCH / FLOW unter dem HUD, /dmga flow oder dem Minikartenmenü.",
  ["Equipped trinkets you can use. Ticked: shown in the items badge beside slot 1 when SimC uses it (with your big cooldowns). Unticked: never shown."] = "Angelegte Schmuckstücke mit Benutzen-Effekt. Angehakt: im Gegenstands-Abzeichen neben Platz 1 gezeigt, wenn SimC es benutzt (mit deinen großen Abklingzeiten). Nicht angehakt: nie gezeigt.",
  ["Every equipped on-use trinket and every spell can be switched off on the Spells, trinkets & potion page."] = "Jedes angelegte Schmuckstück mit Benutzeffekt und jeder Zauber kann auf der Seite Zauber, Schmuckstücke & Trank abgeschaltet werden.",
  ["Everything else is in three groups, each with pages inside: click the + beside DMGAssist on the left to see them, or open one here."] = "Alles Weitere steht in drei Gruppen mit eigenen Seiten: klicke links auf das + neben DMGAssist, um sie zu sehen, oder öffne eine hier.",
  ["Flow mode & grades has more pages inside it: click the + beside it on the left, or open one here."] = "Flow-Modus & Bewertungen hat weitere Seiten: klicke links auf das + daneben, oder öffne eine hier.",
  ["Flow: notes, bars and colours"] = "Flow: Noten, Balken und Farben",
  ["Flow: what you see"] = "Flow: was du siehst",
  ["For %s. What DMGAssist may show you, in three parts: the potion it suggests with your big cooldowns, your on-use trinkets, and your spells. Kept per spec (trinkets per item), through updates and gear swaps."] = "Für %s. Was DMGAssist dir zeigen darf, in drei Teilen: der Trank zu deinen großen Abklingzeiten, deine Schmuckstücke mit Benutzen-Effekt und deine Zauber. Pro Spezialisierung gespeichert (Schmuckstücke pro Gegenstand), auch über Updates und Ausrüstungswechsel.",
  ["How it works"] = "So funktioniert es",
  ["More settings"] = "Weitere Einstellungen",
  ["No potion chosen. Click the box and pick one from your bags: DMGAssist then suggests it in the items badge beside slot 1 when SimC drinks a potion (with your big cooldowns)."] = "Kein Trank gewählt. Klicke auf das Feld und wähle einen aus deinen Taschen: DMGAssist schlägt ihn dann im Gegenstands-Abzeichen neben Platz 1 vor, wenn SimC einen Trank nimmt (mit deinen großen Abklingzeiten).",
  ["None equipped: only trinkets with a Use: effect are listed here. Equip one and it shows up."] = "Keins angelegt: hier stehen nur Schmuckstücke mit einem Benutzen-Effekt. Lege eins an, dann erscheint es.",
  ["Open"] = "Öffnen",
  ["Out of combat, a missing buff goes in slot 1: raid buffs, shields, weapon imbues, poisons, and Earth Shield or Beacon of Light on your tank. Each can be hidden on the Spells, trinkets & potion page."] = "Außerhalb des Kampfes kommt ein fehlender Buff in Feld 1: Schlachtzugsbuffs, Schilde, Waffenverzauberungen, Gifte sowie Erdschild oder Flamme des Glaubens auf deinem Tank. Jeder kann auf der Seite Zauber, Schmuckstücke & Trank verborgen werden.",
  ["Pages inside"] = "Unterseiten",
  ["Pick a size and a place: that's all most players need. Everything below is optional fine-tuning; changing it shows Custom here."] = "Wähle Größe und Platz: mehr brauchen die meisten nicht. Alles darunter ist optionales Feintuning; änderst du es, steht hier Benutzerdefiniert.",
  ["Place"] = "Platz",
  ["Potion"] = "Trank",
  ["Right after it happens: /dmga report (or the minimap menu, or the Report an issue button at the top of this page). Step 1: say what went wrong. Step 2: Ctrl+C copies your words and the report together. Step 3: open the link and paste it into a new issue. /dmga help lists every command."] = "Direkt nachdem es passiert ist: /dmga report (oder das Minikarten-Menü oder die Schaltfläche Problem melden oben auf dieser Seite). Schritt 1: sag, was schiefging. Schritt 2: Strg+C kopiert deine Worte und den Bericht zusammen. Schritt 3: öffne den Link und füge alles in ein neues Issue ein. /dmga help listet alle Befehle auf.",
  ["Right now"] = "Gerade jetzt",
  ["Size, layout, fonts, keybind text, badges and what the HUD shows."] = "Größe, Anordnung, Schriften, Tastentext, Abzeichen und was das HUD zeigt.",
  ["Small, medium or large: the whole HUD, icons and text. Custom: set by the Scale slider below."] = "Klein, mittel oder groß: das ganze HUD, Symbole und Text. Benutzerdefiniert: über den Skalierungsregler unten.",
  ["Sounds for interrupts, defensives, boss calls and cooldowns."] = "Klänge für Unterbrechungen, Defensivzauber, Boss-Warnungen und Abklingzeiten.",
  ["Spells"] = "Zauber",
  ["Spells (notes) slide from right to left into the box on the left. A note reaches the box exactly when it can be pressed: the box flashes, press it then. Perfect, Great or Good says how close you were. Every hit adds to your streak and score (under the lane); every 10 in a row raises the multiplier, up to x4. Stars and a rank (Bronze to Mythic) grow with the streak. A red X: wrong spell, the streak breaks. Waiting (moving, a mechanic, nothing to press) never breaks it."] = "Zauber (Noten) gleiten von rechts nach links in das Feld links. Eine Note erreicht das Feld genau dann, wenn sie gedrückt werden kann: das Feld blinkt, dann drücken. Perfekt, Super oder Gut sagt, wie genau du warst. Jeder Treffer erhöht Serie und Punkte (unter der Spur); alle 10 in Folge steigt der Multiplikator, bis x4. Sterne und ein Rang (Bronze bis Mythisch) wachsen mit der Serie. Ein rotes X: falscher Zauber, die Serie reißt. Warten (Laufen, eine Mechanik, nichts zu drücken) reißt sie nie.",
  ["Spells, trinkets & potion"] = "Zauber, Schmuckstücke & Trank",
  ["Spells, trinkets & potion: untick a spell or trinket to never see it, or tick First when ready to put a spell in slot 1 whenever it can be cast. Kept per spec, through updates."] = "Zauber, Schmuckstücke & Trank: entferne den Haken bei einem Zauber oder Schmuckstück, um es nie zu sehen, oder hake Zuerst, wenn bereit an, um einen Zauber in Feld 1 zu setzen, sobald er gewirkt werden kann. Pro Spezialisierung gespeichert, auch über Updates.",
  ["The note in the box is always exactly the spell Classic shows: that is never changed. To keep the lane readable, Flow smooths what comes after it: the notes behind only swap when a new pick holds for a third of a second, a spell the rotation keeps putting off is hidden after being passed over three times, notes never slide backwards (they pause and flow on), only one note stands in the box, and the lane pauses when there's nothing to press for 6 seconds. So the lane is calmer than Classic's small icons, never less right about what to press now. Score, streaks and stars are for fun and for learning the rhythm: they never change what is recommended. Flow timing offset (Flow mode & grades) moves the flash for your latency."] = "Die Note im Feld ist immer genau der Zauber, den Klassisch zeigt: das wird nie verändert. Damit die Spur lesbar bleibt, glättet Flow, was danach kommt: die Noten dahinter tauschen erst, wenn eine neue Wahl eine Drittelsekunde hält, ein Zauber, den die Rotation ständig verschiebt, wird nach dreimal Übergehen ausgeblendet, Noten gleiten nie rückwärts (sie halten an und fließen weiter), nur eine Note steht im Feld, und die Spur pausiert, wenn 6 Sekunden nichts zu drücken ist. Die Spur ist also ruhiger als die kleinen Symbole von Klassisch, aber nie weniger richtig beim Zauber für jetzt. Punkte, Serien und Sterne sind zum Spaß und um den Rhythmus zu lernen: sie ändern nie, was empfohlen wird. Flow-Timing-Versatz (Flow-Modus & Bewertungen) verschiebt das Blinken für deine Latenz.",
  ["The rhythm-game mode, its timing, and the performance grade."] = "Der Rhythmusspiel-Modus, sein Timing und die Leistungsnote.",
  ["Ticked: may be shown. Unticked: never shown (the next spell takes its place). First when ready: in slot 1 whenever it can be cast (only interrupts, defensives and gap closers come before it)."] = "Angehakt: kann gezeigt werden. Nicht angehakt: nie gezeigt (der nächste Zauber rückt nach). Zuerst wenn bereit: auf Platz 1, sobald er gewirkt werden kann (nur Unterbrechungen, Defensivzauber und Sprungzauber kommen davor).",
  ["Timing, debugging and the rarely needed switches."] = "Timing, Fehlersuche und selten gebrauchte Schalter.",
  ["Turn DMGAssist on or off, move it, and pick its language. More settings are at the bottom of this page."] = "Schalte DMGAssist ein oder aus, verschiebe es und wähle seine Sprache. Weitere Einstellungen findest du unten auf dieser Seite.",
  ["Two ways to play"] = "Zwei Spielweisen",
  ["What DMGAssist sees right now, a guide to Classic and Flow, what every tag, badge and colour means, and Report an issue."] = "Was DMGAssist gerade sieht, eine Anleitung zu Klassisch und Flow, was jede Markierung, jedes Abzeichen und jede Farbe bedeutet, und Problem melden.",
  ["What Flow changes to stay fun"] = "Was Flow für den Spielspaß anpasst",
  ["What to recommend, single target or AoE, interrupts, defensives, trinkets, buff reminders and leveling."] = "Was empfohlen wird, Einzelziel oder Flächenschaden, Unterbrechungen, Defensivzauber, Schmuckstücke, Buff-Erinnerungen und Leveln.",
  ["When the grade shows, what it measures, and its place."] = "Wann die Note erscheint, was sie misst und wo sie steht.",
  ["Where the HUD sits. Custom: wherever you dragged it (unlock on the first page) or put it in Edit Mode."] = "Wo das HUD sitzt. Benutzerdefiniert: dort, wohin du es gezogen hast (auf der ersten Seite entsperren) oder im Bearbeitungsmodus.",
  ["Yellow bar behind a note: a cast, as long as the cast. Blue bar: a channel. Orange, burning note: a major cooldown, worth double. Faded note: a guess or waiting for resource; it doesn't count as a miss. Lane turns electric blue (POWER MODE!): Bloodlust or right after a major cooldown; every hit scores double. The row above the lane holds bonuses to grab when they're needed: INTERRUPT!, DEFEND! (a defensive or heal) and POWER UP! (a trinket or potion). After a set of pulls (20 seconds out of combat), your performance grade shows."] = "Gelber Balken hinter einer Note: ein Zauber mit Zauberzeit, so lang wie diese. Blauer Balken: ein kanalisierter Zauber. Orange, brennende Note: eine große Abklingzeit, zählt doppelt. Blasse Note: eine Schätzung oder wartet auf Ressource; zählt nicht als Fehler. Die Spur wird elektrisch blau (POWER-MODUS!): Kampfrausch oder direkt nach einer großen Abklingzeit; jeder Treffer zählt doppelt. Die Reihe über der Spur bietet Boni, wenn sie gebraucht werden: UNTERBRECHEN!, VERTEIDIGEN! (Defensivzauber oder Heilung) und POWER UP! (Schmuckstück oder Trank). Nach einer Reihe von Pulls (20 Sekunden außerhalb des Kampfes) erscheint deine Leistungsnote.",
  ["Your best grade, recent sets and where to improve, for this spec."] = "Deine beste Note, letzte Durchgänge und wo du dich verbessern kannst, für diese Spezialisierung.",
  ["Your potion, your on-use trinkets and every spell, each on or off for this spec."] = "Dein Trank, deine Schmuckstücke mit Benutzen-Effekt und jeder Zauber, jeweils ein oder aus für diese Spezialisierung.",
  ["Custom"] = "Benutzerdefiniert",
  ["Just above the action bars"] = "Direkt über den Aktionsleisten",
}
